SELECT cs.canonical_smiles, sub_cr.compound_name AS substrate_compound_name, drug_cr.compound_name AS parent_compound_name, m.met_conversion, m.pathway_key, m.organism, m.enzyme_name FROM metabolism m INNER JOIN compound_records sub_cr ON m.substrate_record_id = sub_cr.record_id INNER JOIN molecule_dictionary md ON sub_cr.molregno = md.molregno INNER JOIN compound_structures cs ON md.molregno = cs.molregno INNER JOIN compound_records drug_cr ON m.drug_record_id = drug_cr.record_id WHERE m.organism = 'Canis lupus familiaris' ORDER BY cs.canonical_smiles, sub_cr.compound_name, drug_cr.compound_name, m.met_conversion, m.pathway_key, m.organism, m.enzyme_name LIMIT 200
